function [stop] = gimbal_stopped(failed, kind, gi, n, j, gfailed)
%GIMBAL_STOPPED  Whether gimbal j (from 0) is stopped: it has failed, or the CMG rotor it turns has (a failed CMG's gimbal command is
%   ignored, S11.7, M5).
%   failed: bool[DYN_NR] (passed true or false)
%   kind: RotorKind[DYN_NR] (passed a choice, as its option's number)
%   gi: int[DYN_NR] (passed a whole number)
%   n: int (passed a whole number)
%   j: int (passed a whole number)
%   gfailed: bool (passed true or false)
%   returns stop: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    stop = false;
    stop = gfailed;
    for i = (0):((n) - 1)
        if ((failed((i) + 1) && (kind((i) + 1) == 2)) && (gi((i) + 1) == (j + 1)))
            stop = true;
        end
    end
end
